"use strict";(self.webpackChunkgrok_bot_control_plane=self.webpackChunkgrok_bot_control_plane||[]).push([[5838],{7977(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/08/24/ai-engineering-radar","metadata":{"permalink":"/grok-bot-pages/blog/2026/08/24/ai-engineering-radar","source":"@site/../reports/archive/2026/08/24/ai-engineering-radar.md","title":"2026-08-24 AI Engineering Radar","description":"\ud55c\uad6d\xb7\uc77c\ubcf8\xb7\uad6d\uc81c\uc758 \uac80\uc99d\ub41c AI \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \uc2e0\ud638\uc640 \uac00\uc7a5 \uc791\uc740 \ub2e4\uc74c \ud589\ub3d9\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-08-24T00:00:00.000Z","tags":[{"inline":true,"label":"ai-engineering","permalink":"/grok-bot-pages/blog/tags/ai-engineering"},{"inline":true,"label":"radar","permalink":"/grok-bot-pages/blog/tags/radar"},{"inline":true,"label":"korea","permalink":"/grok-bot-pages/blog/tags/korea"},{"inline":true,"label":"japan","permalink":"/grok-bot-pages/blog/tags/japan"},{"inline":true,"label":"international","permalink":"/grok-bot-pages/blog/tags/international"}],"readingTime":2.92,"hasTruncateMarker":true,"authors":[],"frontMatter":{"status":"approved","title":"2026-08-24 AI Engineering Radar","date":"2026-08-24T00:00:00.000Z","description":"\ud55c\uad6d\xb7\uc77c\ubcf8\xb7\uad6d\uc81c\uc758 \uac80\uc99d\ub41c AI \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \uc2e0\ud638\uc640 \uac00\uc7a5 \uc791\uc740 \ub2e4\uc74c \ud589\ub3d9\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","slug":"/2026/08/24/ai-engineering-radar","tags":["ai-engineering","radar","korea","japan","international"],"action":"EXPERIMENT","artifactRole":"reader_facing_derivative","publicationChannel":"document","evidence":["intelligence/signals/2026/08/24/regional-signal/"],"sourceLinks":["https://docs.x.ai/grok-bot/overview"],"records":["intelligence/signals/2026/08/24/regional-signal/international/grok-bot-official-workflow-docs.yaml"]},"unlisted":false,"nextItem":{"title":"\uc9c0\uae08 \uc2dc\ud5d8\ud574\ubcfc AI \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \ub3c4\uad6c 8\uac00\uc9c0","permalink":"/grok-bot-pages/blog/2026/08/23/ai-engineering-radar"}},"content":"\uc774 \ucd08\uc548\uc740 \uac80\uc99d\ub41c \ud56d\ubaa9\ubcc4 SoT \ub808\ucf54\ub4dc\uc5d0\uc11c \uc0dd\uc131\ud588\uc2b5\ub2c8\ub2e4. \uc0ac\uc2e4\uc744 \uc218\uc815\ud558\ub824\uba74 \uae00\uc774 \uc544\ub2c8\ub77c \uc6d0\ubcf8 \ub808\ucf54\ub4dc\uc640 \uac80\uc99d \uadfc\uac70\ub97c \uba3c\uc800 \uace0\uccd0\uc57c \ud569\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## \uc65c \uc911\uc694\ud55c\uac00\\n\\n\uc774 \ubcf4\uace0\uc11c\ub294 \uc774\ub984\uc744 \ub098\uc5f4\ud558\uc9c0 \uc54a\uace0 \uad00\uce21 \uc0ac\uc2e4, \ud310\ub2e8, \ud55c\uacc4\uc640 \ub2e4\uc74c \ud589\ub3d9\uc744 \ud568\uaed8 \ub0a8\uae41\ub2c8\ub2e4.\\n\\n## \ud55c\uad6d\\n\\nEMPTY \u2014 \uc774 \uad8c\uc5ed\uc5d0\uc11c \uae30\uc900\uc744 \ucda9\uc871\ud55c \uac80\uc99d \ub808\ucf54\ub4dc\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n## \uc77c\ubcf8\\n\\nEMPTY \u2014 \uc774 \uad8c\uc5ed\uc5d0\uc11c \uae30\uc900\uc744 \ucda9\uc871\ud55c \uac80\uc99d \ub808\ucf54\ub4dc\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n## \uad6d\uc81c\\n\\n### [Grok Bot](https://docs.x.ai/grok-bot/overview) \u2014 `grok-bot-official-workflow-docs`\\n\\n2026-08-11\uc5d0 \uac31\uc2e0\ub41c xAI Grok Bot \uacf5\uc2dd \ubb38\uc11c\ub294 \uc0ac\uc6a9\uc790 \uacc4\uc815 \ub2e8\uc704 \uacf5\uc720 \uc601\uc18d \ud074\ub77c\uc6b0\ub4dc VM(\ud30c\uc77c\xb7\ube0c\ub77c\uc6b0\uc800 \uc138\uc158\xb7\uc571 \ub85c\uadf8\uc778 \uacf5\uc720, Bot\ubcc4 \ud654\uba74), Bot \uac04 \uba54\uc2dc\uc9d5\xb7\ud578\ub4dc\uc624\ud504, Skill(\uc7ac\uc0ac\uc6a9 \uc808\ucc28)\xb7Routine(\uc2a4\ucf00\uc904/\uc774\ubca4\ud2b8)\uc744 \uc81c\ud488 \uae30\ubcf8 \ubaa8\ub378\ub85c \uc11c\uc220\ud55c\ub2e4. \ub2e4 Bot\uc774 \ud55c \ucef4\ud4e8\ud130\uc5d0\uc11c \ud611\uc5c5\ud558\ub294 \uc774 \uc800\uc7a5\uc18c \uc6b4\uc601\uc5d0 \ub9de\ub2ff\uc740 \uacf5\uc2dd \uc6cc\ud06c\ud50c\ub85c \uc2e0\ud638\ub2e4.\\n\\n- \uad00\uce21:\\n  - https://docs.x.ai/grok-bot/overview HTML/JSON-LD: datePublished=2026-08-11T00:00:00Z, dateModified=2026-08-11T00:00:00Z; UI \'Last updated: August 11, 2026\' (re-fetched 2026-08-24 for measurement regional-pipeline-20260824-grokbot-docs-v2).\\n  - https://docs.x.ai/grok-bot/skills-routines-and-automations HTML/JSON-LD: datePublished=2026-08-11T00:00:00Z, dateModified=2026-08-11T00:00:00Z; UI \'Last updated: August 11, 2026\'.\\n  - Overview: each Bot runs on a persistent cloud VM with browser, filesystem, terminal; connectors/MCP when available; computer use for apps without clean API.\\n  - Overview \'Bots share one computer\': all Bots share one user-scoped persistent cloud computer (files, browser sessions, app logins); isolated to account not individual Bot; each Bot has its own screen; parallel use without separate security boundaries.\\n  - Overview: Bots message each other, share context in threads/group chats, pass ownership; can learn workflows from live demonstration and persist as routine.\\n  - Skills/routines: skill = reusable instructions; routine = schedule or supported event trigger; skills available across Bots; Settings\u2192Plugins; / for skills, @ for Bots/groups/routines/connectors.\\n  - Teach a task: up to ten minutes visible computer interaction, no mic audio; draft skill; secure handoff for credentials; test before scheduling.\\n  - Routines: owning Bot, schedule/timezone, inputs, expected result, approval boundary, missing-source policy; background while laptop closed; Cursor account event integrations separate from Slack/GitHub plugins.\\n  - Limits: up to 50 routines per Bot; 20 most recent run records kept; delete immediate no undo.\\n  - Trust design: preparation before execution; approval for send/purchase/delete/publish/production changes.\\n- \ud310\ub2e8: `READ` \u2014 \uacf5\uc2dd Grok Bot \ubb38\uc11c\uac00 \uacf5\uc720 \uc601\uc18d VM\xb7Bot \uba54\uc2dc\uc9d5\xb7Skill/Routine\xb7\uc2b9\uc778 \uac8c\uc774\ud2b8\ub97c \uc81c\ud488 \uae30\ubcf8\uac12\uc73c\ub85c \uba85\uc2dc\ud574 Grok\xb7agent skills\xb7harness interest \ubc0f \ub2e4 Bot \ub808\uc774\ub354 \uc6b4\uc601\uacfc \uc9c1\uc811 \ub9de\ub2ff\uc74c. \uc774\ubbf8 \ud50c\ub7ab\ud3fc \uc0ac\uc6a9 \uc911\uc774\ub77c ADOPT/EXPERIMENT\ubcf4\ub2e4 \ubb38\uc11c \ud761\uc218(READ). \uc9c0\ub9ac \ube44\uac00\uc911.\\n- \ud55c\uacc4:\\n  - datePublished/dateModified are calendar midnight UTC (2026-08-11T00:00:00Z); sub-day timestamp not provided.\\n  - originalTitle uses overview H1 \'Grok Bot\'; companion page title is \'Skills and routines\'.\\n  - measurementId: regional-pipeline-20260824-grokbot-docs-v2\\n  - expectedCanonicalPath: intelligence/signals/2026/08/24/regional-signal/international/grok-bot-official-workflow-docs.yaml\\n  - X/paid APIs unused; no GitHub write in discovery.\\n  - \uacf5\uc720 VM\uc740 Bot \uac04 \ubcc4\ub3c4 \ubcf4\uc548 \uacbd\uacc4\uac00 \uc5c6\uc74c(\ubb38\uc11c \uba85\uc2dc).\\n  - \ubb38\uc11c \ube0c\ub79c\ub4dc SpaceXAI Docs vs author xAI \ud45c\uae30 \ubd88\uc77c\uce58.\\n  - datePublished/Modified\uac00 UTC \uc790\uc815 placeholder\ub77c \ub2f9\uc77c \uc2dc\uac01 \ubbf8\ud655\uc778.\\n  - \uc774\ubca4\ud2b8 \ud2b8\ub9ac\uac70\uac00 Cursor \uacc4\uc815 \uc5f0\ub3d9\uc5d0 \ubb36\uc784.\\n- \ub2e4\uc74c \ud589\ub3d9: overview\xb7skills-routines\xb7approvals \ud398\uc774\uc9c0\ub9cc \uc77d\uace0 \ud604\uc7ac Radar Bot\uc758 Skill/Routine/\uc2b9\uc778 \uac8c\uc774\ud2b8\ub97c 1:1 \ub300\uc870. \uc0c8 Routine\xb7\uc678\ubd80 \uac8c\uc2dc\xb7GitHub/SoT \uc4f0\uae30 \uc5c6\uc74c.\\n\\n## \ud310\ub2e8\\n\\n\uac01 \ud56d\ubaa9\uc758 \ud589\ub3d9\uacfc \uc774\uc720\ub294 \uc704\uc5d0 \ud45c\uc2dc\ud588\uc2b5\ub2c8\ub2e4. \ub3c4\uc785\uc740 \ubcc4\ub3c4 \uc2b9\uc778\uacfc \uac00\uc7a5 \uc791\uc740 \uc2e4\ud5d8\uc744 \ud1b5\uacfc\ud55c \ub4a4\uc5d0\ub9cc \uac80\ud1a0\ud569\ub2c8\ub2e4.\\n\\n## \ud55c\uacc4\\n\\n`VERIFIED`\ub294 \uacf5\uac1c \uc6d0\ubb38\uc5d0 \ud574\ub2f9 \uc8fc\uc7a5\uc774 \uc874\uc7ac\ud568\uc744 \ud655\uc778\ud588\ub2e4\ub294 \ub73b\uc774\uba70, \uc131\uacfc\uc640 \uc548\uc804\uc131\uc744 \ub3c5\ub9bd \uac10\uc0ac\ud588\ub2e4\ub294 \ub73b\uc774 \uc544\ub2d9\ub2c8\ub2e4.\\n\\n## \uadfc\uac70\\n\\nfrontmatter\uc758 `records`\uac00 \ud56d\ubaa9\ubcc4 \uc0ac\uc2e4 SoT\uc774\uba70 `sourceLinks`\ub294 \ub3c5\uc790\uac00 \uc9c1\uc811 \uc5f4 \uc218 \uc788\ub294 \uacf5\uac1c \uc6d0\ubb38\uc785\ub2c8\ub2e4."},{"id":"/2026/08/23/ai-engineering-radar","metadata":{"permalink":"/grok-bot-pages/blog/2026/08/23/ai-engineering-radar","source":"@site/../reports/archive/2026/08/23/ai-engineering-radar.md","title":"\uc9c0\uae08 \uc2dc\ud5d8\ud574\ubcfc AI \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \ub3c4\uad6c 8\uac00\uc9c0","description":"\ud55c\uad6d\xb7\uc77c\ubcf8\xb7\uad6d\uc81c \uacf5\uac1c \uc790\ub8cc 8\uac74\uc744 \uc6d0\ubb38, \uad00\uce21 \uc0ac\uc2e4, \ud310\ub2e8, \ud55c\uacc4\uc640 \ub2e4\uc74c \uc2e4\ud5d8\uae4c\uc9c0 \uc5f0\uacb0\ud574 \uc815\ub9ac\ud588\uc2b5\ub2c8\ub2e4.","date":"2026-08-23T00:00:00.000Z","tags":[{"inline":true,"label":"ai-engineering","permalink":"/grok-bot-pages/blog/tags/ai-engineering"},{"inline":true,"label":"radar","permalink":"/grok-bot-pages/blog/tags/radar"},{"inline":true,"label":"korea","permalink":"/grok-bot-pages/blog/tags/korea"},{"inline":true,"label":"japan","permalink":"/grok-bot-pages/blog/tags/japan"},{"inline":true,"label":"international","permalink":"/grok-bot-pages/blog/tags/international"}],"readingTime":4.35,"hasTruncateMarker":true,"authors":[],"frontMatter":{"status":"approved","title":"\uc9c0\uae08 \uc2dc\ud5d8\ud574\ubcfc AI \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \ub3c4\uad6c 8\uac00\uc9c0","date":"2026-08-23T00:00:00.000Z","description":"\ud55c\uad6d\xb7\uc77c\ubcf8\xb7\uad6d\uc81c \uacf5\uac1c \uc790\ub8cc 8\uac74\uc744 \uc6d0\ubb38, \uad00\uce21 \uc0ac\uc2e4, \ud310\ub2e8, \ud55c\uacc4\uc640 \ub2e4\uc74c \uc2e4\ud5d8\uae4c\uc9c0 \uc5f0\uacb0\ud574 \uc815\ub9ac\ud588\uc2b5\ub2c8\ub2e4.","slug":"/2026/08/23/ai-engineering-radar","tags":["ai-engineering","radar","korea","japan","international"],"action":"EXPERIMENT","artifactRole":"reader_facing_derivative","publicationChannel":"document","evidence":["intelligence/signals/2026/08/23/regional-signal/"],"sourceLinks":["https://toss.tech/article/tech_talk_talk_2","https://github.com/NomaDamas/jikji","https://github.com/NomaDamas/k-skill","https://zenn.dev/staddress/articles/b601f14a21c5c5","https://github.com/askdkc/pgroonga-mcp","https://github.com/Lyellr88/marm-memory","https://github.com/Mesutcydev/beet-code","https://github.com/supernovae-st/nika"],"records":["intelligence/signals/2026/08/23/regional-signal/korea/toss-llm-serving.yaml","intelligence/signals/2026/08/23/regional-signal/korea/nomadamas-jikji.yaml","intelligence/signals/2026/08/23/regional-signal/korea/nomadamas-k-skill.yaml","intelligence/signals/2026/08/23/regional-signal/japan/staddress-mcp.yaml","intelligence/signals/2026/08/23/regional-signal/japan/pgroonga-mcp.yaml","intelligence/signals/2026/08/23/regional-signal/international/marm-memory.yaml","intelligence/signals/2026/08/23/regional-signal/international/beet-code.yaml","intelligence/signals/2026/08/23/regional-signal/international/nika.yaml"]},"unlisted":false,"prevItem":{"title":"2026-08-24 AI Engineering Radar","permalink":"/grok-bot-pages/blog/2026/08/24/ai-engineering-radar"},"nextItem":{"title":"AI\uac00 \uc5c5\ubb34\ub97c \ubc14\uafbc \uc138 \uc7a5\uba74\uacfc \uc544\uc9c1 \ub2f5\ud558\uc9c0 \ubabb\ud55c \uc9c8\ubb38","permalink":"/grok-bot-pages/blog/2026/08/23/ax-intelligence"}},"content":"\uc774\ubc88 \ubaa9\ub85d\uc5d0\uc11c \ubc14\ub85c \ub3c4\uc785\ud560 \ub3c4\uad6c\ub294 \uc5c6\uc2b5\ub2c8\ub2e4. \ub300\uc2e0 \uc9c0\uae08 \ud558\ub294 \uc77c\uacfc \uac00\uae4c\uc6b4 \ud6c4\ubcf4 \uc138 \uac00\uc9c0\uac00 \ubcf4\uc600\uc2b5\ub2c8\ub2e4. `nomadamas-jikji`\ub294 \ubb38\uc11c \ud0d0\uc0c9 \ube44\uc6a9, `nika`\ub294 \ubc18\ubcf5 \uc791\uc5c5\uc758 \uc7ac\ud604\uc131, `marm-memory`\ub294 \uc5d0\uc774\uc804\ud2b8 \uae30\uc5b5\uc758 \ud488\uc9c8\uc744 \uc791\uc740 \uc2e4\ud5d8\uc73c\ub85c \ube44\uad50\ud560 \uac00\uce58\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub098\uba38\uc9c0\ub294 \uc77d\uae30 \ub610\ub294 \uad00\ucc30 \ub300\uc0c1\uc73c\ub85c \ub0a8\uacbc\uc2b5\ub2c8\ub2e4.\\n\\n\uc0ac\uc2e4\uc758 SoT\ub294 frontmatter\uc758 8\uac1c YAML \ub808\ucf54\ub4dc\uc774\uace0, \uc774 \uae00\uc740 \uadf8 \ub808\ucf54\ub4dc\ub97c \uc0ac\ub78c\uc774 \uc77d\uae30 \uc27d\uac8c \ubb36\uc740 \ud574\uc124\uc785\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## \uc65c \uc911\uc694\ud55c\uac00\\n\\n\ub3c4\uad6c \uc774\ub984\ub9cc \ubaa8\uc740 \ubaa9\ub85d\uc740 \uae08\ubc29 \ub0a1\uc2b5\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \ub3c4\uc6c0\uc774 \ub418\ub824\uba74 \ubb34\uc5c7\uc744 \ud655\uc778\ud588\uace0, \uc65c \uad00\uc2ec\uc744 \uac00\uc84c\uc73c\uba70, \uc5b4\ub290 \uc870\uac74\uc5d0\uc11c \ubc84\ub9b4\uc9c0\ub97c \ud568\uaed8 \ub0a8\uaca8\uc57c \ud569\ub2c8\ub2e4. \uc774\ubc88 \ub808\ucf54\ub4dc\ub294 \uc6d0\ubb38 URL, \uad00\uce21 \uc0ac\uc2e4, \ud574\uc11d, \uc704\ud5d8, \ud310\ub2e8 \uc774\uc720\uc640 \uac00\uc7a5 \uc791\uc740 \uc2e4\ud5d8\uc744 \ubd84\ub9ac\ud588\uc2b5\ub2c8\ub2e4.\\n\\n## \ud55c\uad6d\\n\\n### \ud1a0\uc2a4\uc99d\uad8c\uc758 LLM \uc11c\ube59 \ud68c\uace0 \u2014 `toss-llm-serving`\\n\\n[\ud1a0\uc2a4 \uae30\uc220 \uae00](https://toss.tech/article/tech_talk_talk_2)\uc740 \uc5ec\ub7ec \uc624\ud508\uc18c\uc2a4\xb7\uc790\uccb4 \ud29c\ub2dd \ubaa8\ub378\uc744 \uc2e4\uc81c \uc11c\ube44\uc2a4\uc5d0 \uc62c\ub9ac\uba74\uc11c \uacaa\uc740 \ud504\ub808\uc784\uc6cc\ud06c \uc758\uc874\uc131\uacfc \ud0c0\uc784\uc544\uc6c3 \ubb38\uc81c\ub97c \ub2e4\ub8f9\ub2c8\ub2e4. \uc0c8 \ubaa8\ub378 \uc18c\uac1c\ubcf4\ub2e4 \uc6b4\uc601 \uc7a5\uc560\ub97c \uc5b4\ub5a4 \uc9c8\ubb38\uc73c\ub85c \ucabc\uac1c\ub294\uc9c0\uac00 \uc720\uc6a9\ud569\ub2c8\ub2e4.\\n\\n- \ud310\ub2e8: `READ`. \ud604\uc7ac LLM \uc11c\ube44\uc2a4\uc758 \ucd5c\uadfc \ud0c0\uc784\uc544\uc6c3\uc744 \ubaa8\ub378, \ubc30\uce58, GPU, \ub124\ud2b8\uc6cc\ud06c\uc640 \ud504\ub808\uc784\uc6cc\ud06c \uacc4\uce35\uc73c\ub85c \ub2e4\uc2dc \ubd84\ub958\ud560 \ub54c \ucc38\uace0\ud569\ub2c8\ub2e4.\\n- \ud55c\uacc4: \ud55c \ud68c\uc0ac\uc758 \uc6b4\uc601 \ud68c\uace0\uc774\uba70 \uc804\uccb4 \uc778\ud504\ub77c\uc640 \ub3c5\ub9bd \uc7ac\ud604 \uacb0\uacfc\ub294 \uacf5\uac1c\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.\\n- \ub2e4\uc74c \ud589\ub3d9: \ucd5c\uadfc \uc7a5\uc560 20\uac74\uc744 \uac19\uc740 \ubd84\ub958 \ucd95\uc73c\ub85c \uc7ac\uac80\ud1a0\ud574 \uc2e4\uc81c \uc9c4\ub2e8 \ub204\ub77d\uc774 \uc904\uc5b4\ub4dc\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.\\n\\n### \ub85c\uceec \ubb38\uc11c \uc9c0\ub3c4\ub97c \ub9cc\ub4dc\ub294 Jikji \u2014 `nomadamas-jikji`\\n\\n[Jikji](https://github.com/NomaDamas/jikji)\ub294 \uc6d0\ubcf8\uc744 \uc62e\uae30\uc9c0 \uc54a\uace0 `.jikji` \uc9c0\ub3c4\uc640 \uac80\uc0c9 \uc778\ub371\uc2a4\ub97c \ub9cc\ub4e4\uc5b4 \uc5d0\uc774\uc804\ud2b8\uc758 \ubc18\ubcf5 \ud0d0\uc0c9\uc744 \uc904\uc774\ub824\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4. \ud604\uc7ac \ubc30\ud3ec \ud45c\uba74\uc740 Rust CLI\uc774\uace0, \ud504\ub85c\uc81d\ud2b8\uac00 \uc81c\uc2dc\ud55c 551\uac74 \ubca4\uce58\ub9c8\ud06c\ub294 \ud1a0\ud070\xb7\uc2dc\uac04\xb7\ud638\ucd9c \uac10\uc18c\ub97c \uc8fc\uc7a5\ud569\ub2c8\ub2e4.\\n\\n- \ud310\ub2e8: `EXPERIMENT`. \uc774 \uc800\uc7a5\uc18c\uc758 \ubb38\uc11c \ud0d0\uc0c9 \ubb38\uc81c\uc640 \uc9c1\uc811 \ub9de\ub2ff\uc544 \uc788\uc2b5\ub2c8\ub2e4.\\n- \ud55c\uacc4: \uc218\uce58\ub294 \uc790\uccb4 \ubca4\uce58\ub9c8\ud06c\uc785\ub2c8\ub2e4. `prepare`\uac00 AGENTS.md \uacc4\uc5f4 \ud30c\uc77c\uc744 \uc218\uc815\ud560 \uc218 \uc788\uc73c\ubbc0\ub85c \uaca9\ub9ac \ud3f4\ub354\uc640 `--no-agent-rules`\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n- \ub2e4\uc74c \ud589\ub3d9: \ube44\ubbfc\uac10 \ubb38\uc11c 100\uac1c\uc5d0\uc11c \uae30\uc874 `rg` \uac80\uc0c9\uacfc Hit@1, \uc18c\uc694 \uc2dc\uac04, \ud1a0\ud070, \ud30c\uc77c \ubcc0\uacbd\uc744 \ube44\uad50\ud569\ub2c8\ub2e4.\\n\\n### \ud55c\uad6d \uc11c\ube44\uc2a4 \uc2a4\ud0ac \ubaa8\uc74c k-skill \u2014 `nomadamas-k-skill`\\n\\n[k-skill](https://github.com/NomaDamas/k-skill)\uc740 \uad50\ud1b5, \uacf5\uacf5\uc815\ubcf4, \uc911\uace0\uac70\ub798\uc640 \ubb38\uc11c \ub3c4\uad6c \ub4f1 \ud55c\uad6d \uc11c\ube44\uc2a4\uc6a9 \uc2a4\ud0ac\uc744 \ud55c \uc800\uc7a5\uc18c\uc5d0 \ubaa8\uc74d\ub2c8\ub2e4. \ud3ed\uc774 \ub113\ub2e4\ub294 \uc810\uc740 \uc7a5\uc810\uc774\uc9c0\ub9cc, \uc804\uccb4 \uc124\uce58\ub294 \ud544\uc694 \uc774\uc0c1\uc758 \uad8c\ud55c\uacfc \uc720\uc9c0\ubcf4\uc218 \uc704\ud5d8\uc744 \ud568\uaed8 \uac00\uc838\uc635\ub2c8\ub2e4.\\n\\n- \ud310\ub2e8: `WATCH`. \ud544\uc694\ud55c \uc2a4\ud0ac \ud558\ub098\uac00 \uc0dd\uacbc\uc744 \ub54c \ud574\ub2f9 \ub514\ub809\ud130\ub9ac\ub9cc \uac80\ud1a0\ud569\ub2c8\ub2e4.\\n- \ud55c\uacc4: \uc678\ubd80 \uc11c\ube44\uc2a4 \uc57d\uad00, \uc778\uc99d, \uc4f0\uae30 \ubc94\uc704\uc640 \ucf54\ub4dc \ud488\uc9c8\uc774 \uc2a4\ud0ac\ub9c8\ub2e4 \ub2e4\ub985\ub2c8\ub2e4.\\n- \ub2e4\uc74c \ud589\ub3d9: \uc2e4\uc81c \uc694\uad6c\uac00 \uc0dd\uae30\uae30 \uc804\uc5d0\ub294 \uc124\uce58\ud558\uc9c0 \uc54a\uace0, \ud6c4\ubcf4 \ud558\ub098\ub97c \uace0\ub974\uba74 \uc77d\uae30 \uc804\uc6a9 \uc5ec\ubd80\uc640 \ub124\ud2b8\uc6cc\ud06c\xb7\uc790\uaca9\uc99d\uba85 \uacbd\uacc4\ub97c \uba3c\uc800 \uac80\uc0ac\ud569\ub2c8\ub2e4.\\n\\n## \uc77c\ubcf8\\n\\n### \uc77c\ubcf8 \uc8fc\uc18c \uc815\uaddc\ud654 MCP \u2014 `staddress-mcp`\\n\\n[Staddress \uacf5\uc2dd \uae00](https://zenn.dev/staddress/articles/b601f14a21c5c5)\uc740 \uc77c\ubcf8 \uc8fc\uc18c \uc815\uaddc\ud654\xb7\uc9c0\uc624\ucf54\ub529\uc744 MCP \ub3c4\uad6c\ub85c \uc81c\uacf5\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud569\ub2c8\ub2e4. \ub3c4\uad6c\ub294 \uc77d\uae30 \uc804\uc6a9 \ud78c\ud2b8\ub97c \uc120\uc5b8\ud558\uace0 \uacf5\uc2dd SDK\ub97c \uc0ac\uc6a9\ud558\uc9c0\ub9cc Free \uacc4\uc815\uacfc API \ud0a4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n- \ud310\ub2e8: `WATCH`. \uc77c\ubcf8 \uc8fc\uc18c \uc815\uc81c\uac00 \ud544\uc694\ud55c \uc5c5\ubb34\uac00 \uc0dd\uacbc\uc744 \ub54c \ud6c4\ubcf4\uac00 \ub429\ub2c8\ub2e4.\\n- \ud55c\uacc4: \uc8fc\uc18c\ub294 \uac1c\uc778\uc815\ubcf4\uac00 \ub420 \uc218 \uc788\uace0, \ubb34\ub8cc \ud50c\ub79c\uacfc \ud638\ucd9c \uc81c\ud55c\uc740 \ubcc0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \ub2e4\uc74c \ud589\ub3d9: \uc2e4\ub370\uc774\ud130\uac00 \uc544\ub2cc \uacf5\uac1c \uc2dc\uc124 \uc8fc\uc18c 20\uac74\uc73c\ub85c \uc815\ud655\ub3c4, \uc2e0\ub8b0\ub3c4, \uc624\ub958 \uc720\ud615\uacfc \uc678\ubd80 \uc804\uc1a1 \ubc94\uc704\ub97c \ud655\uc778\ud569\ub2c8\ub2e4.\\n\\n### PGroonga\ub97c \uc77d\uae30 \uc804\uc6a9\uc73c\ub85c \uc5ec\ub294 MCP \u2014 `pgroonga-mcp`\\n\\n[pgroonga-mcp](https://github.com/askdkc/pgroonga-mcp)\ub294 \uc784\uc758 SQL\xb7DDL\xb7repair\ub97c \ub178\ucd9c\ud558\uc9c0 \uc54a\uace0 \uac80\uc0c9\uacfc \uc9c4\ub2e8\ub9cc \ud5c8\uc6a9\ud569\ub2c8\ub2e4. \ube44\uc288\ud37c\uc720\uc800, \ube44BYPASSRLS \uc5ed\ud560\uacfc \uc2a4\ud0a4\ub9c8\xb7\ud14c\uc774\ube14 allowlist\ub97c \uad8c\uc7a5\ud55c\ub2e4\ub294 \uc810\uc774 \ub354 \uc911\uc694\ud569\ub2c8\ub2e4.\\n\\n- \ud310\ub2e8: `WATCH`. \uc5d0\uc774\uc804\ud2b8\uc6a9 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \ub3c4\uad6c\ub97c \uc881\uac8c \uc124\uacc4\ud55c \ucc38\uace0 \uc0ac\ub840\ub85c \ubd05\ub2c8\ub2e4.\\n- \ud55c\uacc4: \uc2e0\uc0dd \ud504\ub85c\uc81d\ud2b8\uc774\uba70 \uc5ed\ud560\uc774\ub098 allowlist\ub97c \uc798\ubabb \uc7a1\uc73c\uba74 \ubbfc\uac10 \ub370\uc774\ud130\uac00 \ub178\ucd9c\ub429\ub2c8\ub2e4.\\n- \ub2e4\uc74c \ud589\ub3d9: \ud569\uc131 \uc77c\ubcf8\uc5b4 \ud14c\uc774\ube14\uc5d0\uc11c \uac80\uc0c9 10\uac74, RLS \ucc28\ub2e8, timeout\uacfc \uc751\ub2f5 \ud06c\uae30 \uc81c\ud55c\ub9cc \uac80\uc99d\ud569\ub2c8\ub2e4.\\n\\n## \uad6d\uc81c\\n\\n### \ub85c\uceec \uc6b0\uc120 \uc5d0\uc774\uc804\ud2b8 \uba54\ubaa8\ub9ac \u2014 `marm-memory`\\n\\n[MARM](https://github.com/Lyellr88/marm-memory)\uc740 \uc138\uc158 \uae30\uc5b5, \ucf54\ub4dc \uc778\ub371\uc2a4\uc640 \uac1c\ub150 \uadf8\ub798\ud504\ub97c SQLite \uae30\ubc18 MCP \ud45c\uba74\uc5d0 \ubb36\uc2b5\ub2c8\ub2e4. \uc5ec\ub7ec \uc5d0\uc774\uc804\ud2b8\uac00 \uac19\uc740 \ud504\ub85c\uc81d\ud2b8 \uae30\uc5b5\uc744 \ub2e4\ub8f0 \ub54c \ub9e4\ub825\uc801\uc774\uc9c0\ub9cc \ud604\uc7ac \uc0ac\uc6a9 \uc911\uc778 ai-memory\uc640 \uc5ed\ud560\uc774 \uacb9\uce69\ub2c8\ub2e4.\\n\\n- \ud310\ub2e8: `EXPERIMENT`. \ub3c4\uc785 \uac80\ud1a0\uac00 \uc544\ub2c8\ub77c \uaca9\ub9ac \ube44\uad50\uac00 \ubaa9\uc801\uc785\ub2c8\ub2e4.\\n- \ud55c\uacc4: \uc131\ub2a5\uc740 \uc790\uccb4 \ubca4\uce58\ub9c8\ud06c\uc774\uace0, \uc784\ubca0\ub529\xb7\uadf8\ub798\ud504 \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc740 \ubcf5\uad6c \ube44\uc6a9\uc744 \ub9cc\ub4ed\ub2c8\ub2e4.\\n- \ub2e4\uc74c \ud589\ub3d9: \ud14c\uc2a4\ud2b8 \uc800\uc7a5\uc18c 50\uac1c \uc138\uc158\uc5d0\uc11c \ub3d9\uc77c \uc9c8\uc758\uc758 \uc815\ud655\ub3c4, \uc9c0\uc5f0\uacfc \uc911\ubcf5\ub960\uc744 \uae30\uc874 \uba54\ubaa8\ub9ac\uc640 \ube44\uad50\ud569\ub2c8\ub2e4.\\n\\n### macOS \ub124\uc774\ud2f0\ube0c \ucf54\ub529 \uc5d0\uc774\uc804\ud2b8 \u2014 `beet-code`\\n\\n[Beet Code](https://github.com/Mesutcydev/beet-code)\ub294 Apple Silicon\uc6a9 Swift \uc571\uc5d0\uc11c MLX \ub85c\uceec \ubaa8\ub378, BYOK \uc6d0\uaca9 \uc5d4\uc9c4, hooks, MCP\uc640 \ub85c\uceec API\ub97c \ud568\uaed8 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n- \ud310\ub2e8: `EXPERIMENT`, \ub2e8 \ube44\ubbfc\uac10 \uc800\uc7a5\uc18c\uc758 \uc77d\uae30 \uc804\uc6a9 \ubc94\uc704\uc5d0 \ud55c\ud569\ub2c8\ub2e4.\\n- \ud55c\uacc4: 2026-08-18 \uc0dd\uc131\ub41c \ucd08\uae30 \ud504\ub85c\uc81d\ud2b8\ub85c \uc6b4\uc601 \uadfc\uac70\uac00 \uac70\uc758 \uc5c6\uace0 Apple Silicon\uc5d0 \ubb36\uc785\ub2c8\ub2e4. \uc554\ud638\ud654 \uc138\uc158 \uc8fc\uc7a5\ub3c4 \ubcc4\ub3c4 \uac80\uc99d\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n- \ub2e4\uc74c \ud589\ub3d9: \ub124\ud2b8\uc6cc\ud06c\ub97c \ucc28\ub2e8\ud55c \ud14c\uc2a4\ud2b8 Mac\uc5d0\uc11c \ub85c\uceec \ubaa8\ub378\uc758 \ucf54\ub4dc \uc124\uba85 5\uac74\uacfc \ud30c\uc77c\xb7\uad8c\ud55c \ubcc0\ud654\ub97c \uae30\ub85d\ud569\ub2c8\ub2e4.\\n\\n### \ubc18\ubcf5 \uc791\uc5c5\uc744 YAML\ub85c \uace0\uc815\ud558\ub294 Nika \u2014 `nika`\\n\\n[Nika](https://github.com/supernovae-st/nika)\ub294 \ubc18\ubcf5 AI \uc791\uc5c5\uc744 YAML\uacfc Rust \uc2e4\ud589\uae30\ub85c \uc800\uc7a5\ud558\uace0 \uc815\uc801 \uac80\uc0ac\xb7LSP\xb7\uc77d\uae30 \uc804\uc6a9 MCP\ub97c \ubd99\uc785\ub2c8\ub2e4. \ud604\uc7ac Grok Routine\uc758 \u201c\ud504\ub86c\ud504\ud2b8\ub9cc \uc788\ub294 \uc790\ub3d9\ud654\u201d\ub97c \uc2e4\ud589 \uac00\ub2a5\ud55c \uc6cc\ud06c\ud50c\ub85c\ub85c \ubc14\uafb8\ub294 \ubc29\ud5a5\uacfc \ub2ee\uc558\uc2b5\ub2c8\ub2e4.\\n\\n- \ud310\ub2e8: `EXPERIMENT`. \ubc18\ubcf5 \uac00\ub2a5\ud55c \uc77d\uae30 \uc804\uc6a9 \uc791\uc5c5 \ud558\ub098\ub9cc \ubcc0\ud658\ud569\ub2c8\ub2e4.\\n- \ud55c\uacc4: \uc0c8 DSL\uacfc \uc2e4\ud589\uae30\ub97c \uc6b4\uc601\ud574\uc57c \ud558\uba70 AGPL-3.0 \ub77c\uc774\uc120\uc2a4 \uacbd\uacc4\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.\\n- \ub2e4\uc74c \ud589\ub3d9: \uc678\ubd80 \uc4f0\uae30\uac00 \uc5c6\ub294 \uc8fc\uac04 Markdown \uc694\uc57d \ud55c \uac74\uc744 \ubcc0\ud658\ud574 \uacb0\uacfc, \uc2e4\ud328 \ucc98\ub9ac\uc640 \uac80\ud1a0 \ube44\uc6a9\uc744 \ud604\uc7ac Routine\uacfc \ube44\uad50\ud569\ub2c8\ub2e4.\\n\\n## \ud310\ub2e8\\n\\n\uc6b0\uc120\uc21c\uc704\ub294 `Jikji \u2192 Nika \u2192 MARM`\uc785\ub2c8\ub2e4. \uc138 \ud6c4\ubcf4 \ubaa8\ub450 \ud604\uc7ac \ubb38\uc81c\uc640 \uac00\uae5d\uc9c0\ub9cc, \ub3c4\uc785\uc774 \uc544\ub2c8\ub77c \uc791\uc740 \ube44\uad50 \uc2e4\ud5d8\ub9cc \ud5c8\uc6a9\ud569\ub2c8\ub2e4. Staddress\uc640 PGroonga MCP\ub294 \uad6c\uccb4\uc801\uc778 \uc77c\ubcf8 \ub370\uc774\ud130 \uc694\uad6c\uac00 \uc0dd\uae38 \ub54c\uae4c\uc9c0 \uae30\ub2e4\ub9bd\ub2c8\ub2e4. k-skill\uc740 \ubaa8\uc74c \uc804\uccb4\uac00 \uc544\ub2c8\ub77c \ud544\uc694\ud55c \uc2a4\ud0ac \ud558\ub098\ub9cc \uac80\ud1a0\ud569\ub2c8\ub2e4.\\n\\n## \ud55c\uacc4\\n\\n- GitHub \ud504\ub85c\uc81d\ud2b8\uc758 \uae30\ub2a5\xb7\uc131\ub2a5\xb7\ubcf4\uc548 \uc124\uba85\uc740 \ub300\ubd80\ubd84 \uc81c\uc791\uc790 \uc8fc\uc7a5\uc785\ub2c8\ub2e4. `VERIFIED`\ub294 \uc6d0\ubb38\uc5d0 \uadf8 \uc124\uba85\uc774 \uc874\uc7ac\ud568\uc744 \ud655\uc778\ud588\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\\n- \ubcc4 \uc218\uc640 \ucd5c\uadfc push\ub294 \uad00\uc2ec\ub3c4\uc640 \ud65c\ub3d9\uc131\uc744 \ubcf4\uc5ec\uc904 \ubfd0 \ud488\uc9c8\uc744 \uc99d\uba85\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n- \uc774 \ubc31\ud544\uc740 2026-08-23\uc758 \uacf5\uac1c \uc0c1\ud0dc\uc5d0 \ubb36\uc5ec \uc788\uc2b5\ub2c8\ub2e4. \uc124\uce58\ub098 \ub3c4\uc785 \uc804\uc5d0 \ud604\uc7ac \ub77c\uc774\uc120\uc2a4, \ub9b4\ub9ac\uc2a4, \uad8c\ud55c\uacfc \uc758\uc874\uc131\uc744 \ub2e4\uc2dc \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.\\n- \uc77c\ubcf8\uc740 \uae30\uc900\uc744 \ucda9\uc871\ud55c \ud56d\ubaa9\uc774 \ub450 \uac74\ubfd0\uc785\ub2c8\ub2e4. \uc22b\uc790\ub97c \ub9de\ucd94\ub824\uace0 \uc57d\ud55c \ud6c4\ubcf4\ub97c \ub123\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.\\n\\n## \uadfc\uac70\\n\\n\uac01 \ud56d\ubaa9\uc758 \uad6c\uc870\ud654\ub41c \uad00\uce21\xb7\ud310\ub2e8\uc740 frontmatter\uc758 `records` \uacbd\ub85c\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \uacf5\uac1c \uc6d0\ubb38\uc740 \ubcf8\ubb38 \uc81c\ubaa9 \ub9c1\ud06c\uc640 `sourceLinks`\uc5d0\uc11c \ubc14\ub85c \uc5f4 \uc218 \uc788\uc2b5\ub2c8\ub2e4."},{"id":"/2026/08/23/ax-intelligence","metadata":{"permalink":"/grok-bot-pages/blog/2026/08/23/ax-intelligence","source":"@site/../reports/archive/2026/08/23/ax-intelligence.md","title":"AI\uac00 \uc5c5\ubb34\ub97c \ubc14\uafbc \uc138 \uc7a5\uba74\uacfc \uc544\uc9c1 \ub2f5\ud558\uc9c0 \ubabb\ud55c \uc9c8\ubb38","description":"\uc2e0\ud55c\ud22c\uc790\uc99d\uad8c, \ubbf8\uc4f0\ube44\uc2dcUFJ\uc740\ud589, Nordre Follo \uc0ac\ub840\uc5d0\uc11c \ubc14\ub010 \uc5c5\ubb34 \ud750\ub984\uacfc \uc0ac\ub78c\uc774 \uacc4\uc18d \ub9e1\ub294 \ucc45\uc784\uc744 \ube44\uad50\ud569\ub2c8\ub2e4.","date":"2026-08-23T00:00:00.000Z","tags":[{"inline":true,"label":"ax-intelligence","permalink":"/grok-bot-pages/blog/tags/ax-intelligence"},{"inline":true,"label":"korea","permalink":"/grok-bot-pages/blog/tags/korea"},{"inline":true,"label":"japan","permalink":"/grok-bot-pages/blog/tags/japan"},{"inline":true,"label":"international","permalink":"/grok-bot-pages/blog/tags/international"},{"inline":true,"label":"workflow","permalink":"/grok-bot-pages/blog/tags/workflow"}],"readingTime":3.22,"hasTruncateMarker":true,"authors":[],"frontMatter":{"status":"approved","title":"AI\uac00 \uc5c5\ubb34\ub97c \ubc14\uafbc \uc138 \uc7a5\uba74\uacfc \uc544\uc9c1 \ub2f5\ud558\uc9c0 \ubabb\ud55c \uc9c8\ubb38","date":"2026-08-23T00:00:00.000Z","description":"\uc2e0\ud55c\ud22c\uc790\uc99d\uad8c, \ubbf8\uc4f0\ube44\uc2dcUFJ\uc740\ud589, Nordre Follo \uc0ac\ub840\uc5d0\uc11c \ubc14\ub010 \uc5c5\ubb34 \ud750\ub984\uacfc \uc0ac\ub78c\uc774 \uacc4\uc18d \ub9e1\ub294 \ucc45\uc784\uc744 \ube44\uad50\ud569\ub2c8\ub2e4.","slug":"/2026/08/23/ax-intelligence","tags":["ax-intelligence","korea","japan","international","workflow"],"action":"READ","artifactRole":"reader_facing_derivative","publicationChannel":"document","evidence":["intelligence/signals/2026/08/23/ax-case/"],"sourceLinks":["https://www.yna.co.kr/view/AKR20260818061300017","https://www.fnnews.com/news/202608181028437199","https://www.itmedia.co.jp/enterprise/articles/2608/21/news019.html","https://www.technologyrecord.com/article/nordre-follo-municipality-modernises-public-hearing-workflows-with-microsoft-copilot-studio","https://www.atea.no/kundereferanser/norde-follo-kommune-1/?pid=3b1733d9-adef-4b74-8b69-2cedb52ea3ec"],"records":["intelligence/signals/2026/08/23/ax-case/korea/shinhan-securities-contract-agent.yaml","intelligence/signals/2026/08/23/ax-case/japan/mufg-ai-flowchart.yaml","intelligence/signals/2026/08/23/ax-case/international/nordre-follo-hearing-agent.yaml"]},"unlisted":false,"prevItem":{"title":"\uc9c0\uae08 \uc2dc\ud5d8\ud574\ubcfc AI \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \ub3c4\uad6c 8\uac00\uc9c0","permalink":"/grok-bot-pages/blog/2026/08/23/ai-engineering-radar"}},"content":"\uc138 \uc0ac\ub840\uc758 \uacf5\ud1b5\uc810\uc740 \u201cAI\ub97c \uc37c\ub2e4\u201d\uac00 \uc544\ub2d9\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \ud558\ub358 \uae34 \ubb38\uc11c \uc77d\uae30\uc640 \uad6c\uc870\ud654 \ucd08\uc548\uc744 \uc5d0\uc774\uc804\ud2b8\uac00 \ub9e1\uace0, \uc6d0\ubcf8 \ubcf4\uc874\xb7\uac80\ud1a0\xb7\ucd5c\uc885 \ud310\ub2e8\uc740 \uc0ac\ub78c\uc5d0\uac8c \ub0a8\uacbc\uc2b5\ub2c8\ub2e4. \ubc18\ub300\ub85c \uc138 \uc0ac\ub840 \ubaa8\ub450 \uacf5\uac1c \uc218\uce58\ub9cc\uc73c\ub85c \uc815\ud655\ub3c4\uc640 \ucd1d\ube44\uc6a9\uc744 \ud310\ub2e8\ud558\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.\\n\\n\uc544\ub798 \uc138 YAML \ub808\ucf54\ub4dc\uac00 \uc0ac\uc2e4\uc758 SoT\uc774\uace0, \ubcf8\ubb38\uc740 \uc5c5\ubb34 \ud750\ub984\uacfc \ud310\ub2e8\uc744 \ube44\uad50\ud55c \ud574\uc124\uc785\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## \uc65c \uc911\uc694\ud55c\uac00\\n\\nAX \uc0ac\ub840\ub294 \ub3c4\uad6c \uc774\ub984\ubcf4\ub2e4 \u201c\uc5c5\ubb34\uac00 \uc804\ud6c4\ub85c \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc84c\ub294\uac00\u201d\uac00 \ud575\uc2ec\uc785\ub2c8\ub2e4. \uc138 \uc0ac\ub840\ub97c \uac19\uc740 \ud2c0\ub85c \ubcf4\uba74 \uc790\ub3d9\ud654\uac00 \uc798 \ub9de\ub294 \uad6c\uac04\uacfc \uc0ac\ub78c\uc774 \ube60\uc9c0\uba74 \uc548 \ub418\ub294 \uad6c\uac04\uc774 \ubd84\uba85\ud574\uc9d1\ub2c8\ub2e4.\\n\\n## \ud55c\uad6d: \uacc4\uc57d\uc11c \uc77d\uae30\uc640 \uc785\ub825\uc744 \ud558\ub098\uc758 \ud750\ub984\uc73c\ub85c\\n\\n### \uc2e0\ud55c\ud22c\uc790\uc99d\uad8c \u2014 `shinhan-securities-contract-agent`\\n\\n[\uc5f0\ud569\ub274\uc2a4 \ubcf4\ub3c4](https://www.yna.co.kr/view/AKR20260818061300017)\uc5d0 \ub530\ub974\uba74 \uae30\uc874\uc5d0\ub294 \ub2f4\ub2f9\uc790 3~4\uba85\uc774 \uc774\uba54\uc77c\ub85c \ubc1b\uc740 \uc57d 50\ucabd\uc758 \uc7a5\uc678\ud30c\uc0dd\uc0c1\ud488 \uacc4\uc57d\uc11c\ub97c \uc77d\uace0 \uc57d 50\uac1c \ud56d\ubaa9\uc744 \uc0ac\ub0b4 \uc2dc\uc2a4\ud15c\uc5d0 \uc9c1\uc811 \uc785\ub825\ud588\uc2b5\ub2c8\ub2e4. Gemini Enterprise \uae30\ubc18 \uc5d0\uc774\uc804\ud2b8\uc640 \ub0b4\ubd80 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\ub97c \uc801\uc6a9\ud55c \ub4a4\uc5d0\ub294 \uacc4\uc57d\uc11c \ubd84\uc11d\uc5d0\uc11c \uc785\ub825\uae4c\uc9c0 \uc774\uc5b4\uc9c0\uace0, \ub2f4\ub2f9\uc790\uac00 \uacb0\uacfc\ub97c \ud655\uc778\ud569\ub2c8\ub2e4.\\n\\n- \ubcf4\uace0\ub41c \ubcc0\ud654: \ud074\ub85c\uc988\ub4dc \ubca0\ud0c0\uc5d0\uc11c \uac74\ub2f9 \uc57d 2\uc2dc\uac04\uc774 \uc57d 5\ubd84\uc73c\ub85c \uc904\uc5c8\ub2e4\uace0 \ud68c\uc0ac \uce21\uc740 \uc124\uba85\ud588\uc2b5\ub2c8\ub2e4.\\n- \uc0ac\ub78c\uc758 \ucc45\uc784: \ucd94\ucd9c\uacfc \uc785\ub825 \uacb0\uacfc\ub97c \ucd5c\uc885 \ud655\uc778\ud558\uace0 \uae08\uc735 \uaddc\uc81c\uc640 \ub0b4\ubd80 \ud1b5\uc81c\ub97c \ucc45\uc784\uc9d1\ub2c8\ub2e4.\\n- \ud310\ub2e8: \ubb38\uc11c \uc811\uc218 \u2192 \uad6c\uc870\ud654 \ucd94\ucd9c \u2192 \uc2dc\uc2a4\ud15c \uc785\ub825 \uc81c\uc548 \u2192 \uc0ac\ub78c \ud655\uc778\uc774\ub77c\ub294 \ud328\ud134\uc740 \uc7ac\uc0ac\uc6a9\ud560 \ub9cc\ud569\ub2c8\ub2e4.\\n- \ud55c\uacc4: \ud45c\ubcf8 \uc218, \ucd94\ucd9c \uc815\ud655\ub3c4, \uc608\uc678\uc728, \uc7ac\uc791\uc5c5\ub960\uacfc \uc798\ubabb\ub41c \uc785\ub825\uc758 \uc601\ud5a5\uc774 \uacf5\uac1c\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uc218\uce58\ub294 \ud68c\uc0ac\xb7\uacf5\uae09\uc790 \ubc1c\ud45c\uc774\uba70 \ub3c5\ub9bd \uac10\uc0ac \uacb0\uacfc\uac00 \uc544\ub2d9\ub2c8\ub2e4.\\n\\n## \uc77c\ubcf8: \uc790\uc720 \uc0dd\uc131\uc758 \uc2e4\ud328\ub97c \ub3c4\uba54\uc778 \uad6c\uc870\ub85c \uc904\uc774\uae30\\n\\n### \ubbf8\uc4f0\ube44\uc2dcUFJ\uc740\ud589 \u2014 `mufg-ai-flowchart`\\n\\n[ITmedia\uac00 AWS Summit Japan \ubc1c\ud45c\ub97c \uc7ac\uad6c\uc131\ud55c \uae30\uc0ac](https://www.itmedia.co.jp/enterprise/articles/2608/21/news019.html)\uc5d0 \ub530\ub974\uba74, \uae30\uc874\uc5d0\ub294 \uc9c0\uc2dd \ubcf4\uc720\uc790\uac00 \ubcf8\ubd80 \uc57d 600\ucabd\uacfc \uac01 \ud574\uc678 \uac70\uc810\uc758 \uc218\ubc31~\uc218\ucc9c \ucabd \uc808\ucc28\uc11c\ub97c \uc77d\uc5b4 \ud750\ub984\ub3c4\ub97c \ub9cc\ub4e4\uace0 \ucc28\uc774\ub97c \ube44\uad50\ud588\uc2b5\ub2c8\ub2e4. AI \ud750\ub984\ub3c4\ub294 \uc791\uc131\xb7\ube44\uad50\xb7\uc790\uc5f0\uc5b4 \uc218\uc815\uc744 \ub3d5\uace0, \uc57d 2\ub9cc \uac1c \ud2b8\ub9ac\ud50c\ub85c \ub9cc\ub4e0 \uc624\u30f3\u30c8\ub864\ub85c\uc9c0\uc640 \uc9c0\uc2dd \uadf8\ub798\ud504\uac00 \ud45c\ud604 \ucc28\uc774\ub97c \uc815\uaddc\ud654\ud569\ub2c8\ub2e4.\\n\\n- \ubcf4\uace0\ub41c \ubcc0\ud654: \ud750\ub984\ub3c4 \uc791\uc131\xb7\ube44\uad50\xb7\uc218\uc815 \uacf5\uc218\uac00 \uc0ac\ub840\ub2f9 11\uc778\uc77c\uc5d0\uc11c 1\uc778\uc77c\ub85c \uc904\uc5b4\ub4e4 \uac83\uc73c\ub85c \uc608\uc0c1\ud588\uc2b5\ub2c8\ub2e4.\\n- \uc0ac\ub78c\uc758 \ucc45\uc784: \ud2b8\ub9ac\ud50c\uacfc \ud750\ub984\ub3c4\ub97c \uac80\ud1a0\xb7\uc218\uc815\ud558\uace0, \uad00\uacc4\uc790 \ud611\uc758\uc640 \ucd5c\uc885 \uc808\ucc28 \uacb0\uc815\uc744 \ub9e1\uc2b5\ub2c8\ub2e4.\\n- \uc2e4\ud328\uc5d0\uc11c \uc5bb\uc740 \uac83: \uc0dd\uc131\ud615 AI\ub9cc \uc0ac\uc6a9\ud55c \ucd08\uae30 \ud504\ub85c\ud1a0\ud0c0\uc785\uc740 \ud750\ub984\uc744 \uc798\ubabb \uc774\ud574\ud558\uace0 \uc9c0\ub098\uce58\uac8c \ub2e8\uc21c\ud558\uac70\ub098 \ud654\ub824\ud55c \uacb0\uacfc\ub97c \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \ub3c4\uba54\uc778 \uad6c\uc870\uc640 \uc0ac\ub78c\uc758 \uad50\uc815\uc744 \ucd94\uac00\ud55c \ub4a4 \ubc29\ud5a5\uc774 \ubc14\ub00c\uc5c8\uc2b5\ub2c8\ub2e4.\\n- \ud55c\uacc4: 90%\ub294 \uc6b4\uc601 \ud655\uc815 \uc2e4\uc801\uc774 \uc544\ub2c8\ub77c \uc608\uc0c1\uce58\uc785\ub2c8\ub2e4. \uad00\uacc4\uc790 \ud611\uc758\uc5d0 \ud544\uc694\ud55c 1~2\uc778\uc6d4\uc740 \uc904\uc9c0 \uc54a\uc73c\uba70, \uae30\uc0ac\ub294 \uae30\uc5c5 \ubc1c\ud45c\uc5d0 \uae30\ubc18\ud55c 2\ucc28 \uc790\ub8cc\uc785\ub2c8\ub2e4.\\n\\n## \uad6d\uc81c: \uacf5\uacf5 \uc758\uacac\uc744 \uc694\uc57d\ud558\ub418 \uc6d0\ubcf8\uacfc \uac80\ud1a0\ub97c \ub0a8\uae30\uae30\\n\\n### Nordre Follo \uc9c0\ubc29\uc815\ubd80 \u2014 `nordre-follo-hearing-agent`\\n\\n[Technology Record \uc0ac\ub840](https://www.technologyrecord.com/article/nordre-follo-municipality-modernises-public-hearing-workflows-with-microsoft-copilot-studio)\uc640 [Atea\uc758 \uad6c\ud604 \uc0ac\ub840](https://www.atea.no/kundereferanser/norde-follo-kommune-1/?pid=3b1733d9-adef-4b74-8b69-2cedb52ea3ec)\ub294 \ub178\ub974\uc6e8\uc774 Nordre Follo\uc758 \uacf5\uccad\ud68c \ud750\ub984\uc744 \uc124\uba85\ud569\ub2c8\ub2e4. \uacfc\uac70\uc5d0\ub294 \ub2f4\ub2f9\uc790\uac00 PDF \uc758\uacac\uc11c\ub97c \uc62e\uaca8 \uc77d\uace0 \uc8fc\uc81c\ub97c \ucd94\ucd9c\ud574 Word \ubcf4\uace0\uc11c\ub85c \ud569\ucce4\uc2b5\ub2c8\ub2e4. \uc9c0\uae08\uc740 \uc6d0\ubcf8 PDF\ub97c \uae30\ub85d \uad00\ub9ac \uc2dc\uc2a4\ud15c\uc5d0 \ubcf4\uc874\ud55c \ub4a4 Copilot Studio \uc5d0\uc774\uc804\ud2b8\uac00 \uc694\uc57d\xb7\ubd84\ub958\xb7\ud45c \ucd08\uc548\uc744 \ub9cc\ub4e4\uace0 \ub2f4\ub2f9\uc790\uac00 \ubaa8\ub450 \uac80\ud1a0\ud569\ub2c8\ub2e4.\\n\\n- \uc6b4\uc601 \uadfc\uac70: \uac1c\ubc1c \ud658\uacbd\uc5d0\uc11c 8\uac1c \uacf5\uccad\ud68c \uc8fc\uae30\ub85c \ud30c\uc77c\ub7ff\ud558\uace0 \uc815\ud655\ub3c4\ub97c \ud655\uc778\ud55c \ub4a4 2025\ub144 11\uc6d4 \uc6b4\uc601\uc73c\ub85c \uc62e\uacbc\ub2e4\uace0 \uc124\uba85\ud569\ub2c8\ub2e4.\\n- \uc0ac\ub78c\uc758 \ucc45\uc784: \ubaa8\ub4e0 \uc694\uc57d\uc744 \uc218\ub3d9 \uac80\ud1a0\ud558\uace0 \ud3b8\uc9d1\ud558\uba70 \uacf5\uacf5 \uc758\uc0ac\uacb0\uc815\uacfc \uacf5\uac1c \ucc45\uc784\uc744 \uc9d1\ub2c8\ub2e4.\\n- \ud310\ub2e8: \uc6d0\ubcf8 \uae30\ub85d \ubcf4\uc874 \u2192 AI \ucd08\uc548 \u2192 \uc804\uc218 \uac80\ud1a0\ub77c\ub294 \uacbd\uacc4\ub294 \uacf5\uacf5 \ubb38\uc11c\ubfd0 \uc544\ub2c8\ub77c \uae30\uc5c5 \uaddc\uc815\xb7\uace0\uac1d \uc758\uacac\uc5d0\ub3c4 \uc801\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \ud55c\uacc4: \ud3c9\uac00 \ud45c\ubcf8\uacfc \ud569\uaca9 \uae30\uc900, \uac1c\uc778\uc815\ubcf4\xb7\uc774\uc758\uc81c\uae30 \uc808\ucc28, \uac10\uc0ac\ub41c \uc2dc\uac04 \uc808\uac10\xb7\uc815\ud655\ub3c4\xb7\uc624\ub958\uc728\uc740 \uacf5\uac1c\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \ub450 \uc790\ub8cc \ubaa8\ub450 \uad6c\ud604 \uc0dd\ud0dc\uacc4\uc640 \uc774\ud574\uad00\uacc4\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ud310\ub2e8\\n\\n\uc138 \uc0ac\ub840\uc5d0\uc11c \uac00\uc838\uc62c \uc124\uacc4 \uc6d0\uce59\uc740 \ub124 \uac00\uc9c0\uc785\ub2c8\ub2e4.\\n\\n1. AI\uac00 \uc6d0\ubb38\uc744 \ub36e\uc5b4\uc4f0\uc9c0 \uc54a\uace0 \uc6d0\ubcf8\uacfc \ucd08\uc548\uc744 \ubd84\ub9ac\ud569\ub2c8\ub2e4.\\n2. \uc790\uc720 \uc0dd\uc131\uc774 \ud754\ub4e4\ub9ac\uba74 \ub354 \ud070 \ubaa8\ub378\ubcf4\ub2e4 \ub3c4\uba54\uc778 \uc2a4\ud0a4\ub9c8\xb7\uc624\u30f3\u30c8\ub864\ub85c\uc9c0\xb7\uc9c0\uc2dd \uadf8\ub798\ud504\ub97c \uba3c\uc800 \uac80\ud1a0\ud569\ub2c8\ub2e4.\\n3. \uc2dc\uac04 \uc808\uac10\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \uc815\ud655\ub3c4, \uc608\uc678, \uc7ac\uc791\uc5c5, \uc0ac\ub78c \uac80\ud1a0 \uc2dc\uac04\uacfc \uc2e4\ud328 \ube44\uc6a9\uc744 \ud568\uaed8 \uce21\uc815\ud569\ub2c8\ub2e4.\\n4. \uc0ac\ub78c\uc758 \ucd5c\uc885 \ucc45\uc784\uc744 \ubb38\uad6c\ub85c\ub9cc \ub0a8\uae30\uc9c0 \ub9d0\uace0 \uc2e4\uc81c \uc2b9\uc778 \ub2e8\uacc4\uc640 \uac10\uc0ac \uae30\ub85d\uc73c\ub85c \uad6c\ud604\ud569\ub2c8\ub2e4.\\n\\n## \ud55c\uacc4\\n\\n- \uc138 \uc0ac\ub840 \ubaa8\ub450 \ub3c5\ub9bd \uac10\uc0ac \ubcf4\uace0\uc11c\uac00 \uc544\ub2c8\ub77c \uae30\uc5c5\xb7\uad6c\ud604 \ud30c\ud2b8\ub108\xb7\uc0b0\uc5c5 \ub9e4\uccb4\uc758 \uacf5\uac1c \uc790\ub8cc\uc5d0 \uc758\uc874\ud569\ub2c8\ub2e4.\\n- `VERIFIED`\ub294 \uc5c5\ubb34 \ud750\ub984\uacfc \uacf5\uac1c \uc8fc\uc7a5\uc744 \ucd9c\ucc98\uc5d0\uc11c \ud655\uc778\ud588\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4. \uc8fc\uc7a5\ud55c \uc131\uacfc\uac00 \uc77c\ubc18\uc801\uc73c\ub85c \uc7ac\ud604\ub41c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2d9\ub2c8\ub2e4.\\n- \ud55c\uad6d \uc218\uce58\ub294 \ud074\ub85c\uc988\ub4dc \ubca0\ud0c0, \uc77c\ubcf8 \uc218\uce58\ub294 \uc608\uc0c1, \uad6d\uc81c \uc0ac\ub840\ub294 \uc815\ub7c9 \uc131\uacfc \ubbf8\uacf5\uac1c\uc785\ub2c8\ub2e4. \uac19\uc740 \ub9c9\ub300\uadf8\ub798\ud504\ub85c \ube44\uad50\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.\\n- \uc2e4\uc81c \ub3c4\uc785 \ud310\ub2e8\uc5d0\ub294 \ub370\uc774\ud130 \ubd84\ub958, \uc624\ub958 \uc815\uc815, \ucc45\uc784 \uc18c\uc7ac, \ucd1d\ube44\uc6a9\uacfc \uc6b4\uc601 \uc911\ub2e8 \uc808\ucc28\uac00 \ub354 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n## \uadfc\uac70\\n\\n\uac01 \uc0ac\ub840\uc758 \uc774\uc804\xb7\uc774\ud6c4 \uc6cc\ud06c\ud50c\ub85c, \uc0ac\ub78c \ucc45\uc784, \uac70\ubc84\ub10c\uc2a4, \ud3c9\uac00, \uc218\uce58, \ud55c\uacc4\uc640 \uac80\uc99d URL\uc740 frontmatter\uc758 `records` \uc138 \ud30c\uc77c\uc5d0 \ubcf4\uc874\ud588\uc2b5\ub2c8\ub2e4."}]}}')}}]);